head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[multiselect > M > validate]<br/>mandatory=true 일때 선택값에 대한 유효성 체크를 실행한 후 결과값을 반환합니다.",
    "validation" : [
        "유효성 체크 결과를 Boolean 으로 반환합니다. (true: 통과, false: 실패)",
        "mandatory=true 이고 선택값이 있으면 유효성 체크를 통과하여 true 를 반환합니다.",
        "mandatory=true 이고 선택값이 없으면 유효성 체크가 실패하여 false 를 반환합니다.",
        "mandatory 속성의 유효성 체크를 통과하지 못하면 체크가 중단됩니다.",
        "displaymessage=true 인 경우 실패 메시지가 출력되며, invalidMessage, invalidMessageFunc 속성으로 실패 메시지를 변경할 수 있습니다.",
        "실패 메시지가 출력된 후 false 를 반환합니다.",
        "유효성 체크를 통과하지 못한 컴포넌트가 포커스 됩니다.",
        "유효성 체크에 대한 반환값으로 자세한 정보를 받으려면 validateObject() 메소드를 사용하여야 합니다.",
        "displaymessage=true 이고 validate() 메소드의 실행결과가 실패일때 alert() 으로 실패 메시지가 표시됩니다.",
        "invalidMessage 속성이 설정되어 있으면 해당 메시지가 alert() 으로 출력됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성 (BindItemSet: gdl_multiselect 와 바인딩, mandatory/displaymessage/invalidMessage 속성 적용)
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // gdl_multiselect 재생성 (idempotent: 기존 dataList 제거 후 재생성)
    $c.gcm.createDataListMultiSelect();

    // 조건 설정
    let cMandatory = con_mandatory.getText();
    let cDisplaymessage = con_displaymessage.getText();
    let cInvalidMessage = par_invalidMessage.getValue();

    let properties = {};
    if (cMandatory !== "") {
        properties.mandatory = cMandatory;
    }
    if (cDisplaymessage !== "") {
        properties.displaymessage = cDisplaymessage;
    }
    if (cInvalidMessage !== "") {
        properties.invalidMessage = cInvalidMessage;
    }
    let cList = $c.gcm.createCList(properties);

    // 현재 적용된 속성 정보 라벨 표시
    let labelText = "target1 : mandatory=[" + (cMandatory === "" ? "미설정(기본 false)" : cMandatory) + "]"
        + ", displaymessage=[" + (cDisplaymessage === "" ? "미설정(기본 false)" : cDisplaymessage) + "]"
        + ", invalidMessage=[" + (cInvalidMessage === "" ? "미설정" : cInvalidMessage) + "]";
    $c.gcm.createLabel('label="' + labelText + '"', '', 'label1');

    // comp 생성 함수 호출
    $c.gcm.createBasicMultiSelect(cList);
}



// validate() 호출 - Boolean 반환값 출력
scwin.btn_validate_onclick = function (e) {
    let rtn = target1.validate();
    wf_body_bottom.getObj("scwin").setReturnValue("target1.validate() : " + rtn);

    if (rtn)
        wf_body_bottom.getObj("scwin").setReturnValue("validate check : PASS");
    else
        wf_body_bottom.getObj("scwin").setReturnValue("validate check : FAIL");
};



// validateObject() 호출 - Object 반환값 출력 (Boolean vs Object 비교용)
scwin.btn_validateObject_onclick = function (e) {
    let rtnObj = target1.validateObject();
    wf_body_bottom.getObj("scwin").setReturnValue("target1.validateObject() : " + JSON.stringify(rtnObj));

    if (rtnObj && rtnObj.type) {
        wf_body_bottom.getObj("scwin").setReturnValue("callerId : " + rtnObj.callerId);
        wf_body_bottom.getObj("scwin").setReturnValue("type : " + rtnObj.type);
        wf_body_bottom.getObj("scwin").setReturnValue("value : " + rtnObj.value);
    }
};



// 아이템 선택 (인덱스 0 선택) - validate 통과 검증용
scwin.btn_selectItem_onclick = function (e) {
    target1.setValue("");
    target1.setSelectedIndexNM(0, true);
    target1.setInstanceValue();
    wf_body_bottom.getObj("scwin").setReturnValue("target1 : 인덱스 0 선택 완료 (getSelectedIndex='" + target1.getSelectedIndex() + "')");
};



// 전체 선택 해제 - validate 실패 케이스 검증용
scwin.btn_clearSelection_onclick = function (e) {
    target1.setValue("");
    target1.setInstanceValue();
    wf_body_bottom.getObj("scwin").setReturnValue("target1 : 전체 선택 해제 완료");
};



// 포커스 확인 - validate 실패 시 컴포넌트 포커스 검증용
scwin.btn_checkFocus_onclick = function (e) {
    let activeId = (document.activeElement) ? document.activeElement.id : "";
    let targetId = (target1.render) ? target1.render.id : "";
    wf_body_bottom.getObj("scwin").setReturnValue("document.activeElement.id : " + activeId);
    wf_body_bottom.getObj("scwin").setReturnValue("target1.render.id : " + targetId);
    wf_body_bottom.getObj("scwin").setReturnValue("focus 일치 여부 : " + (activeId === targetId));
};
